demo.code:
console.log('Edge Impulse pipeline stages:');
['1. Data acquisition','2. Impulse design (DSP + ML blocks)','3. Training','4. EON Compiler export','5. On-device inference'].forEach(function(s,i){console.log(' stage '+ (i+1) +': '+s.split('. ')[1]);});
console.log('Deploy targets: Arduino, Nordic nRF, ST STM32, Espressif ESP32');

var dspMs=12, nnMs=34, ramKB=48, flashKB=210;
console.log('DSP block: '+dspMs+' ms, NN block: '+nnMs+' ms');
console.log('Total latency: '+(dspMs+nnMs)+' ms, RAM '+ramKB+' KB, flash '+flashKB+' KB');
var budget={latencyMs:100,ramKB:64,flashKB:512};
console.log('Fits budget: '+(dspMs+nnMs<=budget.latencyMs && ramKB<=budget.ramKB && flashKB<=budget.flashKB));

var samples=[{label:'idle',n:420},{label:'shake',n:380},{label:'tap',n:400}];
var total=samples.reduce(function(a,s){return a+s.n;},0);
samples.forEach(function(s){var pct=(100*s.n/total).toFixed(1);console.log(s.label+': '+s.n+' samples ('+pct+'%)'+(s.n/total<0.1?' SKEWED':''));});
console.log('Total samples: '+total);

var classes=['idle','shake','tap'];
var conf=[[38,1,1],[2,36,2],[0,1,39]];
var correct=conf.reduce(function(a,row,i){return a+row[i];},0);
var total=conf.reduce(function(a,row){return a+row.reduce(function(x,y){return x+y;},0);},0);
console.log('Confusion matrix accuracy: '+(100*correct/total).toFixed(1)+'%');
classes.forEach(function(c,i){console.log(' '+c+' recall: '+(100*conf[i][i]/conf[i].reduce(function(a,b){return a+b;},0)).toFixed(1)+'%');});

var floatKB=512, ramFloatKB=180;
var int8KB=Math.round(floatKB/4), ramInt8KB=Math.round(ramFloatKB/4);
console.log('float32: flash '+floatKB+' KB, RAM '+ramFloatKB+' KB');
console.log('int8:    flash '+int8KB+' KB, RAM '+ramInt8KB+' KB');
console.log('Savings: '+Math.round(100*(1-int8KB/floatKB))+'% smaller');

function fftBinEnergy(n){var e=[];for(var i=0;i<n;i++)e.push(Math.round(100*Math.exp(-Math.pow(i-n/3,2)/8)));return e;}
var e=fftBinEnergy(16);
console.log('Spectral feature vector (16 bins): '+e.join(','));
console.log('Peak bin: '+e.indexOf(Math.max.apply(null,e))+' (dominant frequency)');

var centroids=[[10,12],[40,38],[70,15]];
function dist(a,b){return Math.hypot(a[0]-b[0],a[1]-b[1]);}
[[11,13],[68,16],[200,200]].forEach(function(p){
  var d=Math.min.apply(null,centroids.map(function(c){return dist(p,c);}));
  console.log('point ('+p+') anomaly score '+d.toFixed(1)+(d>40?' -> ANOMALY':' -> normal'));
});

var verdicts=['normal','normal','tamper','normal'];
var key='device-key-7f3a';
verdicts.forEach(function(v,i){
  var sig=(v+key+i).split('').reduce(function(a,c){return a+c.charCodeAt(0);},0)%997;
  console.log('t+'+i+'s verdict='+v+' sig='+sig+(v!=='normal'?'  ALERT: tamper signature detected':''));
});

var arenaKB=48, stackWorstB=812;
console.log('SDK contract: static arena '+arenaKB+' KB, worst-case stack '+stackWorstB+' B');
function runClassifier(window){var s=window.reduce(function(a,x){return a+x;},0)/window.length;return s>0.5?'tap':'idle';}
console.log('inference on [0.1,0.8,0.9] -> '+runClassifier([0.1,0.8,0.9]));
console.log('inference on [0.0,0.1,0.05] -> '+runClassifier([0.0,0.1,0.05]));

var fails=[{win:12,stage:'dsp'},{win:13,stage:'dsp'},{win:27,stage:'nn'}];
var byStage={};
fails.forEach(function(f){byStage[f.stage]=(byStage[f.stage]||0)+1;});
Object.keys(byStage).forEach(function(s){console.log('stage '+s+': '+byStage[s]+' failing windows');});
console.log('Likely culprit: dsp (feature drift on windows 12-13)');

var grid=[[0,1,0],[0,0,0],[1,0,0]];
var n=0;grid.forEach(function(row,r){row.forEach(function(v,c){if(v){n++;console.log('object centroid at grid ('+r+','+c+')');}});});
console.log('Objects detected: '+n+' (raw frame never leaves the chip)');

var fleet=[{id:'node-01',ver:'1.4.0'},{id:'node-02',ver:'1.3.2'},{id:'node-03',ver:'1.4.0'}];
var target='1.4.0';
fleet.forEach(function(n){console.log(n.id+': '+n.ver+(n.ver===target?' OK':' -> queue signed delta to '+target));});

var layers=['studio accuracy 96.2%','on-device latency 41 ms','field soak: 71.5 h'];
layers.forEach(function(l,i){console.log('layer '+(i+1)+': '+l);});
var fieldAcc=0.941;
console.log('Field accuracy: '+(100*fieldAcc).toFixed(1)+'% (unseen conditions, 3 sites)');

var baseline=12.4;
[12.1,12.8,13.0,18.6,24.3].forEach(function(v,i){
  var ratio=v/baseline;
  console.log('day '+(i+1)+': vibration '+v.toFixed(1)+' (x'+ratio.toFixed(2)+' baseline)'+(ratio>1.4?' -> BEARING ALERT':''));
});

var roadmap=['single-sensor sentinel','multi-modal fusion','on-device adaptation','fleet-wide federated refresh'];
roadmap.forEach(function(s,i){console.log('stage '+(i+1)+': '+s);});
console.log('Discipline: measure on target, test in field, audit every model.');
